edges = []
for i in range(13):
    for j in [1, 2]:
        u = i
        v = (i + j) % 13
        if u > v:
            u, v = v, u
        if (u, v) not in edges:
            edges.append((u, v))

edges.sort()
print(edges)

degrees = [0] * 13
for u, v in edges:
    degrees[u] += 1
    degrees[v] += 1

print(degrees)
